input.content:
:root{
  --bg:#06110c;--bg2:#0a1a12;--card:#0e2118;--card2:#132c20;--line:#24402f;
  --text:#eef6ef;--muted:#93a99a;--lime:#c6ff4d;--lime2:#8ee63f;--gold:#ffc857;
  --red:#ff6b6b;--blue:#7cc7ff;--green:#5ee08a;--shadow:0 18px 50px rgba(0,0,0,.32);
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{
  margin:0;min-height:100vh;color:var(--text);
  font-family:ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;
  background:
    radial-gradient(900px 500px at 85% -10%,rgba(42,110,72,.35),transparent 60%),
    radial-gradient(700px 400px at 5% 110%,rgba(28,76,50,.28),transparent 60%),
    var(--bg);
}
button{font:inherit;color:inherit;cursor:pointer}
button:disabled{opacity:.45;cursor:not-allowed}
h1,h2,h3,p{margin:0}
.app{display:grid;grid-template-columns:236px minmax(0,1fr);min-height:100vh;max-width:1560px;margin:0 auto}
.sidebar{
  position:sticky;top:0;height:100vh;padding:24px 16px 18px;display:flex;flex-direction:column;
  border-right:1px solid var(--line);background:rgba(7,19,13,.72);backdrop-filter:blur(14px);z-index:10;
}
.brand{font-size:21px;font-weight:950;letter-spacing:-1.1px;line-height:1}
.brand span{color:var(--lime)}
.brand small{display:block;margin-top:5px;color:var(--muted);font-size:9px;letter-spacing:2.4px;font-weight:800}
.season-pill{display:flex;align-items:center;gap:8px;margin:18px 0 22px;font-size:11px;color:var(--muted)}
.season-pill b{color:var(--text);font-size:12px}
.div-badge{background:var(--lime);color:#102016;border-radius:999px;padding:3px 9px;font-weight:900;font-size:10px}
.nav{display:grid;gap:6px}
.nav-btn{
  display:flex;align-items:center;gap:11px;border:0;background:transparent;color:var(--muted);
  text-align:left;padding:11px 13px;border-radius:10px;font-weight:750;font-size:13px;transition:.16s;
}
.nav-btn:hover{background:rgba(255,255,255,.04);color:var(--text)}
.nav-btn.active{background:var(--lime);color:#102016;box-shadow:0 8px 22px rgba(198,255,77,.18)}
.nav-btn .ic{width:19px;text-align:center;font-size:15px}
.club-card{margin-top:auto;background:linear-gradient(160deg,var(--card2),var(--card));border:1px solid var(--line);border-radius:14px;padding:13px}
.club-row{display:flex;align-items:center;gap:10px}
.club-row strong{display:block;font-size:13px;line-height:1.2}
.club-row small{display:block;color:var(--muted);font-size:10.5px;margin-top:3px}
.club-meta{display:flex;justify-content:space-between;margin-top:11px;padding-top:10px;border-top:1px solid var(--line);font-size:10.5px;color:var(--muted)}
.club-meta b{color:var(--lime)}
.side-foot{margin-top:10px}
.link-btn{border:0;background:transparent;color:var(--muted);font-size:11px;padding:8px;width:100%;text-align:center}
.link-btn:hover{color:var(--red)}
.main{padding:24px 30px 56px;min-width:0}
.topbar{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;margin-bottom:22px}
.topbar h1{font-size:27px;letter-spacing:-.8px;line-height:1.1}
.topbar p{color:var(--muted);font-size:12px;margin-top:5px}
.top-actions{display:flex;align-items:center;gap:9px;flex-shrink:0}
.save-pill{font-size:10px;color:var(--muted);border:1px solid var(--line);padding:6px 10px;border-radius:999px;background:rgba(14,33,24,.7)}
.save-pill.saving{color:var(--gold)}
.btn{border:1px solid var(--line);background:var(--card);border-radius:9px;padding:10px 15px;font-weight:800;font-size:12px;transition:.16s}
.btn:hover{transform:translateY(-1px);border-color:#3b634b}
.btn-primary{background:var(--lime);color:#102016;border-color:var(--lime);box-shadow:0 8px 24px rgba(198,255,77,.16)}
.btn-primary:hover{background:#d3ff73;border-color:#d3ff73}
.btn-danger{background:rgba(255,107,107,.12);color:#ff9b9b;border-color:rgba(255,107,107,.35)}
.btn-ghost{background:transparent}
.btn-sm{padding:7px 11px;font-size:11px;border-radius:7px}
.btn-block{width:100%}
.screen{display:none;animation:fade .22s ease}
.screen.active{display:block}
@keyframes fade{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:none}}
.grid{display:grid;gap:16px}
.home-grid{grid-template-columns:minmax(0,1.55fr) minmax(300px,.85fr)}
.card{background:linear-gradient(170deg,rgba(19,44,32,.92),rgba(13,30,22,.94));border:1px solid var(--line);border-radius:16px;padding:18px;box-shadow:var(--shadow)}
.card-tight{padding:14px}
.card-head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:13px}
.card-head h2{font-size:14px;letter-spacing:.2px}
.card-head .mini{font-size:10px;color:var(--muted)}
.link{background:transparent;border:0;color:var(--lime);font-size:11px;font-weight:800;padding:2px}
.hero{
  position:relative;overflow:hidden;min-height:316px;display:flex;flex-direction:column;
  background:
    radial-gradient(500px 260px at 85% 0%,rgba(198,255,77,.13),transparent 60%),
    linear-gradient(145deg,#173b2b,#0b1d15 70%);
}
.hero:before{content:"";position:absolute;inset:-40% -10% auto auto;width:420px;height:420px;border:1px solid rgba(198,255,77,.12);border-radius:50%}
.hero:after{content:"";position:absolute;inset:auto -80px -170px auto;width:360px;height:360px;border:1px solid rgba(255,255,255,.05);border-radius:50%}
.hero-top{display:flex;justify-content:space-between;gap:12px;color:var(--muted);font-size:10px;letter-spacing:.7px;text-transform:uppercase;position:relative;z-index:1}
.hero-top b{color:var(--lime)}
.teams{display:flex;align-items:center;justify-content:center;gap:clamp(16px,5vw,56px);padding:26px 0 20px;position:relative;z-index:1;flex:1}
.team{width:140px;text-align:center}
.team .crest{margin:0 auto 10px}
.team b{display:block;font-size:15px;line-height:1.2}
.team small{display:block;color:var(--muted);font-size:10.5px;margin-top:4px}
.vs{font-size:12px;font-weight:950;color:var(--lime);border:1px solid rgba(198,255,77,.3);border-radius:50%;width:38px;height:38px;display:grid;place-items:center;background:rgba(198,255,77,.06)}
.hero-actions{display:flex;gap:9px;position:relative;z-index:1}
.hero-actions .btn{flex:1}
.crest{
  width:74px;height:74px;border-radius:50% 50% 42% 42%;display:grid;place-items:center;
  font-weight:950;font-size:22px;letter-spacing:-.5px;border:4px solid rgba(255,255,255,.16);
  box-shadow:inset 0 -8px 18px rgba(0,0,0,.22),0 12px 28px rgba(0,0,0,.3);
  text-shadow:0 2px 4px rgba(0,0,0,.28);flex-shrink:0;
}
.crest.sm{width:40px;height:40px;font-size:12px;border-width:2px;border-radius:50% 50% 44% 44%}
.crest.xs{width:28px;height:28px;font-size:9px;border-width:2px}
.stat-strip{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:14px}
.stat{background:rgba(6,17,12,.5);border:1px solid var(--line);border-radius:11px;padding:12px}
.stat span{display:block;color:var(--muted);font-size:9.5px;text-transform:uppercase;letter-spacing:.6px}
.stat b{display:block;font-size:21px;margin-top:4px;letter-spacing:-.5px}
.stat small{color:var(--muted);font-size:10px}
.stack{display:grid;gap:16px}
.table-wrap{overflow:auto;border-radius:10px}
.table{width:100%;border-collapse:collapse;font-size:12px;white-space:nowrap}
.table th{text-align:left;color:var(--muted);font-size:9px;letter-spacing:.7px;text-transform:uppercase;padding:7px 8px;font-weight:800}
.table td{padding:8px;border-top:1px solid rgba(36,64,47,.72)}
.table tbody tr{transition:.12s}
.table tbody tr:hover{background:rgba(255,255,255,.025)}
.table tr.me{background:rgba(198,255,77,.075)}
.table tr.me td:first-child{box-shadow:inset 3px 0 0 var(--lime)}
.table .num{text-align:center;font-variant-numeric:tabular-nums}
.table .club-cell{display:flex;align-items:center;gap:8px;min-width:150px}
.table .club-cell b{font-size:11.5px;font-weight:750}
.table .club-cell small{color:var(--muted);font-size:9px}
.zone-blue td:first-child{box-shadow:inset 3px 0 0 var(--blue)}
.zone-green td:first-child{box-shadow:inset 3px 0 0 var(--green)}
.zone-red td:first-child{box-shadow:inset 3px 0 0 var(--red)}
.zone-gold td:first-child{box-shadow:inset 3px 0 0 var(--gold)}
.form{display:flex;gap:3px}
.dot{width:18px;height:18px;border-radius:50%;display:grid;place-items:center;font-size:8px;font-weight:900;color:#08130d;flex-shrink:0}
.dot.w{background:#5ee08a}.dot.d{background:#d4d98a}.dot.l{background:#ff7b7b}.dot.n{background:#31483a;color:#9fb2a4}
.legend{display:flex;flex-wrap:wrap;gap:12px;margin-top:12px;color:var(--muted);font-size:10px}
.legend i{display:inline-block;width:7px;height:7px;border-radius:2px;margin-right:5px;vertical-align:1px}
.tabs{display:flex;gap:7px;overflow-x:auto;padding-bottom:2px;scrollbar-width:none}
.tabs::-webkit-scrollbar{display:none}
.tab{border:1px solid var(--line);background:rgba(14,33,24,.7);color:var(--muted);border-radius:8px;padding:8px 13px;font-size:11px;font-weight:850;white-space:nowrap;transition:.15s}
.tab:hover{color:var(--text);border-color:#3b634b}
.tab.active{background:var(--lime);color:#102016;border-color:var(--lime)}
.tab .tiny{display:block;font-size:8px;font-weight:700;opacity:.7;margin-top:1px}
.fixtures{display:grid;gap:2px}
.fixture{display:grid;grid-template-columns:1fr 54px 1fr;align-items:center;gap:8px;padding:9px 6px;border-bottom:1px solid rgba(36,64,47,.65);font-size:11.5px}
.fixture:last-child{border-bottom:0}
.fixture .fx-home{text-align:right}
.fixture .fx-away{text-align:left}
.fixture .fx-mid{text-align:center;color:var(--muted);font-size:10px;font-weight:800}
.fixture .fx-mid b{color:var(--text);font-size:11px;background:rgba(6,17,12,.6);border:1px solid var(--line);padding:3px 7px;border-radius:5px}
.fixture.me{background:rgba(198,255,77,.055);border-radius:6px}
.fixture .fx-team{display:inline-flex;align-items:center;gap:6px;max-width:100%}
.fixture .fx-away .fx-team{flex-direction:row-reverse}
.fixture .fx-team span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.team-name{font-weight:750}
.team-name.dim{color:var(--muted);font-weight:600}
.mini-table .table td{padding:6px 7px}
.mini-table .table .club-cell{min-width:0}
.obj-card{background:linear-gradient(150deg,rgba(198,255,77,.1),rgba(14,33,24,.9));border-color:rgba(198,255,77,.24)}
.obj-card h2{font-size:12px;color:var(--lime);text-transform:uppercase;letter-spacing:.8px}
.obj-card p{font-size:12.5px;color:#dbe7dd;line-height:1.55;margin-top:8px}
.progress{height:7px;background:rgba(6,17,12,.6);border-radius:6px;overflow:hidden;margin-top:14px;border:1px solid rgba(255,255,255,.05)}
.progress i{display:block;height:100%;background:linear-gradient(90deg,var(--lime2),var(--lime));border-radius:6px;transition:width .4s}
.progress-meta{display:flex;justify-content:space-between;margin-top:6px;font-size:9.5px;color:var(--muted)}
.squad-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(168px,1fr));gap:11px}
.player{background:linear-gradient(165deg,var(--card2),var(--card));border:1px solid var(--line);border-radius:13px;padding:13px;position:relative;overflow:hidden}
.player:after{content:"";position:absolute;right:-22px;top:-30px;width:76px;height:76px;border:1px solid rgba(255,255,255,.045);border-radius:50%}
.player-top{display:flex;justify-content:space-between;align-items:flex-start;gap:6px}
.pos{font-size:8.5px;font-weight:900;letter-spacing:.5px;padding:3px 6px;border-radius:4px;background:rgba(255,255,255,.06);color:var(--muted)}
.pos.GOL{background:rgba(255,200,87,.15);color:var(--gold)}
.pos.ZAG,.pos.LAT{background:rgba(124,199,255,.13);color:var(--blue)}
.pos.VOL,.pos.MEI{background:rgba(94,224,138,.13);color:var(--green)}
.pos.PON,.pos.ATA{background:rgba(198,255,77,.14);color:var(--lime)}
.rating{font-size:20px;font-weight:950;letter-spacing:-.8px;color:var(--lime)}
.player h3{font-size:12.5px;margin-top:10px;line-height:1.25;position:relative;z-index:1}
.player .meta{display:flex;justify-content:space-between;margin-top:5px;color:var(--muted);font-size:9.5px}
.bar{height:4px;background:rgba(6,17,12,.7);border-radius:4px;overflow:hidden;margin-top:10px}
.bar i{display:block;height:100%;background:linear-gradient(90deg,#5cae45,var(--lime));border-radius:4px}
.squad-summary{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:16px}
.squad-summary .stat b{font-size:19px}
.match-grid{grid-template-columns:minmax(0,1.55fr) minmax(300px,.8fr)}
.scoreboard{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:12px;padding:16px 18px}
.sb-team{display:flex;align-items:center;gap:10px;min-width:0}
.sb-team.away{justify-content:flex-end;text-align:right}
.sb-team b{font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.sb-team small{display:block;color:var(--muted);font-size:9.5px;margin-top:2px}
.sb-score{text-align:center;min-width:110px}
.sb-score .score{font-size:34px;font-weight:950;letter-spacing:-2px;line-height:1}
.sb-score .minute{font-size:10px;color:var(--lime);font-weight:850;margin-top:5px;letter-spacing:.5px}
.pitch{
  position:relative;width:100%;aspect-ratio:16/9.4;max-height:470px;border-radius:12px;overflow:hidden;
  border:2px solid rgba(205,240,200,.62);
  background:
    linear-gradient(90deg,rgba(255,255,255,.035) 50%,transparent 50%) 0 0/16.66% 100%,
    linear-gradient(90deg,#2f7a45,#2b7040);
  box-shadow:inset 0 0 60px rgba(0,0,0,.25);
}
.pitch:before{content:"";position:absolute;left:50%;top:0;bottom:0;width:1.5px;background:rgba(255,255,255,.5);transform:translateX(-50%)}
.pitch:after{content:"";position:absolute;left:50%;top:50%;width:17%;aspect-ratio:1;border:1.5px solid rgba(255,255,255,.5);border-radius:50%;transform:translate(-50%,-50%)}
.box{position:absolute;top:24%;height:52%;width:13%;border:1.5px solid rgba(255,255,255,.5)}
.box.left{left:0;border-left:0}.box.right{right:0;border-right:0}
.box.small{top:37%;height:26%;width:6%}
.goal{position:absolute;top:42%;height:16%;width:1.2%;background:rgba(255,255,255,.55)}
.goal.left{left:0}.goal.right{right:0}
.pdot{
  position:absolute;width:25px;height:25px;border-radius:50%;display:grid;place-items:center;
  font-size:8px;font-weight:900;transform:translate(-50%,-50%);z-index:2;
  transition:left .45s ease,top .45s ease;border:2px solid rgba(255,255,255,.82);
  box-shadow:0 3px 9px rgba(0,0,0,.28);
}
.pdot.us{background:#eaf7ee;color:#14351f}
.pdot.them{background:#e05a52;color:#fff}
.ball{position:absolute;width:11px;height:11px;border-radius:50%;background:#fff;z-index:3;transform:translate(-50%,-50%);transition:left .45s ease,top .45s ease;box-shadow:0 2px 7px rgba(0,0,0,.45)}
.ball:after{content:"";position:absolute;inset:2.5px;border:1.5px solid #1b2a20;border-radius:50%}
.match-side{display:grid;gap:12px;align-content:start}
.commentary{display:grid;gap:7px;max-height:230px;overflow:auto;padding-right:3px}
.event{display:flex;gap:8px;font-size:11px;line-height:1.4;color:#c9d8cc;padding:6px 0;border-bottom:1px solid rgba(36,64,47,.5)}
.event:last-child{border-bottom:0}
.event .min{color:var(--lime);font-weight:900;font-size:9.5px;min-width:26px}
.event.goal{color:var(--text);background:rgba(198,255,77,.07);border-radius:6px;padding:7px 8px;border-bottom:0}
.event.goal .min{color:var(--gold)}
.stats-list{display:grid;gap:9px}
.stat-row{display:grid;grid-template-columns:34px 1fr 34px;align-items:center;gap:8px;font-size:10px;color:var(--muted)}
