/* Núcleo da liga: estado, tabelas, simulação e temporadas */
function rand(n) { return Math.floor(Math.random() * n); }
function pick(arr) { return arr[rand(arr.length)]; }
function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }
function shuffle(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = rand(i + 1);
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}
function poisson(lambda) {
  const L = Math.exp(-lambda);
  let k = 0, p = 1;
  do { k++; p *= Math.random(); } while (p > L && k < 12);
  return k - 1;
}

function cloneClub(c) { return Object.assign({}, c); }

function makeTable(clubs) {
  const t = {};
  clubs.forEach(c => {
    t[c.id] = { p: 0, j: 0, v: 0, e: 0, d: 0, gf: 0, gs: 0, gd: 0, form: [] };
  });
  return t;
}

function roundRobin(ids) {
  const arr = ids.slice();
  const n = arr.length;
  const rounds = [];
  for (let r = 0; r < n - 1; r++) {
    const pairs = [];
    for (let i = 0; i < n / 2; i++) {
      const a = arr[i], b = arr[n - 1 - i];
      pairs.push(r % 2 === 0 ? { home: a, away: b } : { home: b, away: a });
    }
    rounds.push(pairs);
    arr.splice(1, 0, arr.pop());
  }
  return rounds;
}

function doubleRoundRobin(ids) {
  const first = roundRobin(ids);
  const second = first.map(round => round.map(m => ({ home: m.away, away: m.home })));
  return first.concat(second);
}

function buildLeagueDiv(id, clubs) {
  const schedule = doubleRoundRobin(clubs.map(c => c.id));
  return {
    id, name: DIV_NAME[id], clubs,
    table: makeTable(clubs), schedule, round: 0, finished: false
  };
}

function buildD(clubs) {
  const player = clubs.find(c => c.id === PLAYER_ID);
  const rest = shuffle(clubs.filter(c => c.id !== PLAYER_ID));
  const groups = 'ABCDEFGH'.split('').map((gid, i) => {
    const gc = i === 0 && player ? [player, ...rest.splice(0, 7)] : rest.splice(0, 8);
    return {
      id: gid, clubs: gc, table: makeTable(gc),
      schedule: doubleRoundRobin(gc.map(c => c.id)), round: 0
    };
  });
  return {
    id: 'D', name: DIV_NAME.D, groups, phase: 'groups', koRound: 0,
    koRounds: [], finished: false, champion: null, promoted: [], playerExit: null
  };
}

function makeSquad() {
  return INITIAL_SQUAD.map(p => Object.assign({ goals: 0 }, p));
}

function createInitialState() {
  return {
    version: 3, season: 2026, playerDivision: 'D', screen: 'home',
    divisions: {
      A: buildLeagueDiv('A', A_CLUBS.map(cloneClub)),
      B: buildLeagueDiv('B', B_CLUBS.map(cloneClub)),
      C: buildLeagueDiv('C', C_CLUBS.map(cloneClub)),
      D: buildD(D_CLUBS.map(cloneClub))
    },
    squad: makeSquad(),
    tactic: 'equilibrado',
    history: [], lastResults: [],
    seasonEnded: false, pendingSeason: null, match: null,
    selectedDivision: 'D', selectedGroup: null
  };
}

let S = null;

function save() {
  try {
    const snapshot = Object.assign({}, S, { match: null });
    localStorage.setItem(SAVE_KEY, JSON.stringify(snapshot));
    const pill = document.getElementById('savePill');
    if (pill) {
      pill.textContent = 'Salvo';
      pill.classList.remove('saving');
    }
  } catch (e) { /* armazenamento indisponível */ }
}

function loadState() {
  try {
    const raw = localStorage.getItem(SAVE_KEY);
    if (!raw) return null;
    const s = JSON.parse(raw);
    if (!s || s.version !== 3 || !s.divisions || !s.squad) return null;
    s.match = null;
    s.pendingSeason = s.pendingSeason || null;
    s.selectedDivision = s.selectedDivision || s.playerDivision;
    s.selectedGroup = s.selectedGroup || null;
    if (!['home', 'league', 'squad', 'match'].includes(s.screen)) s.screen = 'home';
    return s;
  } catch (e) { return null; }
}

function allClubs() {
  const out = [];
  DIV_ORDER.forEach(d => {
    if (d === 'D') S.divisions.D.groups.forEach(g => out.push(...g.clubs));
    else out.push(...S.divisions[d].clubs);
  });
  return out;
}

function getClub(id) {
  return allClubs().find(c => c.id === id) || null;
}

function playerClub() { return getClub(PLAYER_ID); }

function standings(clubs, table) {
  return clubs.map(c => Object.assign({ club: c }, table[c.id]))
    .sort((a, b) =>
      b.p - a.p || b.v - a.v || b.gd - a.gd || b.gf - a.gf ||
      a.club.name.localeCompare(b.club.name, 'pt-BR')
    );
}

function record(table, homeId, awayId, hg, ag) {
  const H = table[homeId], A = table[awayId];
  if (!H || !A) return;
  H.j++; A.j++;
  H.gf += hg; H.gs += ag; A.gf += ag; A.gs += hg;
  H.gd = H.gf - H.gs; A.gd = A.gf - A.gs;
  if (hg > ag) {
    H.p += 3; H.v++; A.d++; H.form.push('V'); A.form.push('D');
  } else if (hg < ag) {
    A.p += 3; A.v++; H.d++; A.form.push('V'); H.form.push('D');
  } else {
    H.p++; A.p++; H.e++; A.e++; H.form.push('E'); A.form.push('E');
  }
  if (H.form.length > 5) H.form.shift();
  if (A.form.length > 5) A.form.shift();
}

function expectedGoals(attack, defense, advantage) {
  const diff = (attack.strength + advantage) - defense.strength;
  return clamp(1.32 * Math.exp(diff / 11), 0.22, 3.9);
}

function simulatePens(home, away) {
  let h = 0, a = 0;
  for (let i = 0; i < 5; i++) {
    if (Math.random() < 0.74) h++;
    if (Math.random() < 0.74) a++;
  }
  let guard = 0;
  while (h === a && guard < 30) {
    h += Math.random() < 0.7 ? 1 : 0;
    a += Math.random() < 0.7 ? 1 : 0;
    guard++;
  }
  if (h === a) h++;
  return [h, a];
}

function simScore(home, away, knockout) {
  const hg = poisson(expectedGoals(home, away, 3));
  const ag = poisson(expectedGoals(away, home, -3));
  let pens = null, winner = null;
  if (knockout && hg === ag) {
    pens = simulatePens(home, away);
    winner = pens[0] > pens[1] ? home : away;
  } else {
    winner = hg > ag ? home : ag > hg ? away : null;
  }
  return { hg, ag, pens, winner };
}

function simulateFixture(f, table) {
  if (f.result) return;
  const r = simScore(getClub(f.home), getClub(f.away), false);
  f.result = { hg: r.hg, ag: r.ag };
  record(table, f.home, f.away, r.hg, r.ag);
}

function simulateLeagueRound(div) {
  if (div.finished || div.round >= div.schedule.length) return;
  div.schedule[div.round].forEach(f => simulateFixture(f, div.table));
  div.round++;
  if (div.round >= div.schedule.length) div.finished = true;
}

function simulateGroupRound(group) {
  if (group.round >= group.schedule.length) return;
  group.schedule[group.round].forEach(f => simulateFixture(f, group.table));
  group.round++;
}

function getPlayerGroup(D) {
  return (D || S.divisions.D).groups.find(g => g.clubs.some(c => c.id === PLAYER_ID)) || null;
}

function playerStatus() {
  const div = S.playerDivision;
  if (div === 'D') {
    const g = getPlayerGroup();
    if (!g) return { pos: 0, pts: 0, j: 0, total: 0, rows: [], group: '-' };
    const rows = standings(g.clubs, g.table);
    const i = rows.findIndex(r => r.club.id === PLAYER_ID);
    return {
      pos: i + 1, pts: rows[i] ? rows[i].p : 0, j: rows[i] ? rows[i].j : 0,
      total: g.clubs.length, rows, group: g.id
    };
  }
  const d = S.divisions[div];
  const rows = standings(d.clubs, d.table);
  const i = rows.findIndex(r => r.club.id === PLAYER_ID);
  return {
    pos: i + 1, pts: rows[i] ? rows[i].p : 0, j: rows[i] ? rows[i].j : 0,
    total: d.clubs.length, rows, group: null
  };
}

function getPlayerFixture() {
  if (S.seasonEnded) return null;
  const div = S.playerDivision;
  if (div !== 'D') {
    const d = S.divisions[div];
    if (d.round >= d.schedule.length) return null;
    const f = d.schedule[d.round].find(m => m.home === PLAYER_ID || m.away === PLAYER_ID);
    return f ? Object.assign({ stage: 'league', div, roundIndex: d.round }, f) : null;
  }
  const D = S.divisions.D;
  if (D.phase === 'groups') {
    const g = getPlayerGroup(D);
    if (!g || g.round >= g.schedule.length) return null;
    const f = g.schedule[g.round].find(m => m.home === PLAYER_ID || m.away === PLAYER_ID);
    return f ? Object.assign({ stage: 'group', groupId: g.id, roundIndex: g.round }, f) : null;
  }
  if (D.phase === 'ko') {
    const round = D.koRounds[D.koRound];
    const i = round.ties.findIndex(t => !t.winner && (t.home === PLAYER_ID || t.away === PLAYER_ID));
    if (i >= 0) {
      const t = round.ties[i];
      return { stage: 'ko', koRound: D.koRound, tieIndex: i, home: t.home, away: t.away };
    }
  }
  return null;
}

function fixtureLabel(fx) {
  if (!fx) return 'Sem partida';
  if (fx.stage === 'league') return `${DIV_NAME[fx.div]} · Rodada ${fx.roundIndex + 1}`;
  if (fx.stage === 'group') return `Série D · Grupo ${fx.groupId} · Rodada ${fx.roundIndex + 1}`;
  if (fx.stage === 'ko') return `Série D · ${KO_NAMES[fx.koRound]}`;
  return 'Partida';
}

function upcomingPlayerFixtures(n) {
  const out = [];
  if (S.playerDivision !== 'D') {
    const d = S.divisions[S.playerDivision];
    for (let r = d.round; r < d.schedule.length && out.length < n; r++) {
      const f = d.schedule[r].find(m => m.home === PLAYER_ID || m.away === PLAYER_ID);
      if (f) out.push(Object.assign({ stage: 'league', div: S.playerDivision, roundIndex: r }, f));
    }
  } else {
    const D = S.divisions.D;
    if (D.phase === 'groups') {
      const g = getPlayerGroup(D);
      if (g) for (let r = g.round; r < g.schedule.length && out.length < n; r++) {
        const f = g.schedule[r].find(m => m.home === PLAYER_ID || m.away === PLAYER_ID);
        if (f) out.push(Object.assign({ stage: 'group', groupId: g.id, roundIndex: r }, f));
      }
    } else if (D.phase === 'ko') {
      const f = getPlayerFixture();
      if (f) out.push(f);
    }
  }
  return out;
}

function rowFor(clubId) {
  for (const d of DIV_ORDER) {
    if (d === 'D') {
      for (const g of S.divisions.D.groups) {
        if (g.table[clubId]) return g.table[clubId];
      }
    } else if (S.divisions[d].table[clubId]) {
      return S.divisions[d].table[clubId];
    }
  }
  return { form: [] };
}

/* ---------- mata-mata da Série D ---------- */
function simulateTie(tie) {
  if (tie.winner) return;
  const r = simScore(getClub(tie.home), getClub(tie.away), true);
  tie.score = [r.hg, r.ag];
  tie.pens = r.pens;
  tie.winner = r.winner;
  tie.simulated = true;
}

function simulateNonPlayerTies(round) {
  round.ties.forEach(t => {
    if (!t.winner && t.home !== PLAYER_ID && t.away !== PLAYER_ID) simulateTie(t);
  });
}

function allDecided(round) { return round.ties.every(t => t.winner); }

function createNextRound(D) {
  const winners = D.koRounds[D.koRound].ties.map(t => t.winner);
  const ties = [];
  for (let i = 0; i < winners.length; i += 2) {
    ties.push({ home: winners[i], away: winners[i + 1], score: null, pens: null, winner: null, simulated: false });
  }
  D.koRound++;
  D.koRounds.push({ name: KO_NAMES[D.koRound], ties });
}

function buildKnockout(D) {
  const q = [];
  D.groups.forEach(g => {
    const top = standings(g.clubs, g.table).slice(0, 2);
    q.push(top[0].club.id, top[1].club.id);
  });
  const pairs = [
    [q[0], q[3]], [q[4], q[7]], [q[8], q[11]], [q[12], q[15]],
    [q[2], q[1]], [q[6], q[5]], [q[10], q[9]], [q[14], q[13]]
  ];
  const ties = pairs.map(p => ({ home: p[0], away: p[1], score: null, pens: null, winner: null, simulated: false }));
  D.koRounds = [{ name: KO_NAMES[0], ties }];
  D.koRound = 0;
  D.phase = 'ko';
  simulateNonPlayerTies(D.koRounds[0]);
  if (!ties.some(t => t.home === PLAYER_ID || t.away === PLAYER_ID)) {
    D.playerExit = 'Fase de grupos';
    simulateRestOfD(D);
  }
}

function advanceKnockout(D) {
  const round = D.koRounds[D.koRound];
  if (!allDecided(round)) return;
  if (D.koRound === 3) { finishD(D); return; }
  createNextRound(D);
  const next = D.koRounds[D.koRound];
  simulateNonPlayerTies(next);
  if (!next.ties.some(t => t.home === PLAYER_ID || t.away === PLAYER_ID)) {
    D.playerExit = KO_NAMES[D.koRound - 1];
    simulateRestOfD(D);
  }
}

function simulateRestOfD(D) {
  if (D.phase !== 'ko') return;
  while (true) {
    const round = D.koRounds[D.koRound];
    round.ties.forEach(t => { if (!t.winner) simulateTie(t); });
    if (D.koRound === 3) break;
    createNextRound(D);
  }
  finishD(D);
}

function finishD(D) {
  D.champion = D.koRounds[3].ties[0].winner;
  D.promoted = D.koRounds[1].ties.map(t => t.winner);
  D.phase = 'done';
  D.finished = true;
}

/* ---------- avanço do resto do mundo ---------- */
function advanceLeague(div) {
  if (!div.finished && div.round < div.schedule.length) simulateLeagueRound(div);
}

function advanceD(D) {
  if (D.finished) return;
  if (D.phase === 'groups') {
    D.groups.forEach(g => { if (g.round < g.schedule.length) simulateGroupRound(g); });
    if (D.groups.every(g => g.round >= g.schedule.length)) {
      buildKnockout(D);
      if (D.phase === 'ko') simulateRestOfD(D);
    }
  } else if (D.phase === 'ko') {
    simulateRestOfD(D);
  }
}

function advanceOtherDivisions() {
  DIV_ORDER.forEach(id => {
    if (id === S.playerDivision) return;
    if (id === 'D') advanceD(S.divisions.D);
    else advanceLeague(S.divisions[id]);
  });
}

function applyPlayerResult(m) {
  if (m.stage === 'league') {
    const div = S.divisions[m.div];
    const round = div.schedule[m.roundIndex];
    const f = round.find(x => x.home === m.home.id && x.away === m.away.id);
    if (f) f.result = { hg: m.score[0], ag: m.score[1] };
    record(div.table, m.home.id, m.away.id, m.score[0], m.score[1]);
    round.forEach(x => { if (!x.result) simulateFixture(x, div.table); });
    div.round++;
    if (div.round >= div.schedule.length) div.finished = true;
    return;
  }
  if (m.stage === 'group') {
    const D = S.divisions.D;
    const g = D.groups.find(x => x.id === m.groupId);
    if (!g) return;
    const round = g.schedule[m.roundIndex];
    const f = round.find(x => x.home === m.home.id && x.away === m.away.id);
    if (f) f.result = { hg: m.score[0], ag: m.score[1] };
    record(g.table, m.home.id, m.away.id, m.score[0], m.score[1]);
    round.forEach(x => { if (!x.result) simulateFixture(x, g.table); });
    g.round++;
    D.groups.forEach(og => {
      if (og.id !== g.id && og.round < og.schedule.length) simulateGroupRound(og);
    });
    if (D.groups.every(x => x.round >= x.schedule.length)) buildKnockout(D);
    return;
  }
  if (m.stage === 'ko') {
    const D = S.divisions.D;
    const round = D.koRounds[m.koRound];
    const tie = round.ties[m.tieIndex];
    if (!tie) return;
    tie.score = [m.score[0], m.score[1]];
    tie.pens = m.pens || null;
    tie.winner = m.winner;
    tie.simulated = true;
    simulateNonPlayerTies(round);
    if (allDecided(round)) advanceKnockout(D);
  }
}

function checkSeasonEnd() {
  if (S.seasonEnded) return;
  if (S.playerDivision === 'D') {
    if (S.divisions.D.phase === 'done' || S.divisions.D.finished) endSeason();
  } else {
    const d = S.divisions[S.playerDivision];
    if (d.finished || d.round >= d.schedule.length) endSeason();
  }
}

function fastForwardAll() {
  DIV_ORDER.forEach(id => {
    const d = S.divisions[id];
    if (id === 'D') {
      if (d.phase === 'groups') {
        d.groups.forEach(g => { while (g.round < g.schedule.length) simulateGroupRound(g); });
        buildKnockout(d);
      }
      if (d.phase === 'ko') simulateRestOfD(d);
    } else {
      while (d.round < d.schedule.length) simulateLeagueRound(d);
      d.finished = true;
    }
  });
}

function buildSeasonSummary() {
  const stA = standings(S.divisions.A.clubs, S.divisions.A.table);
  const stB = standings(S.divisions.B.clubs, S.divisions.B.table);
  const stC = standings(S.divisions.C.clubs, S.divisions.C.table);
  const D = S.divisions.D;
  const pd = S.playerDivision;
  let playerPosition = '—', playerOutcome = '', playerPromoted = false, playerRelegated = false;

  if (pd === 'D') {
    playerPromoted = D.promoted.includes(PLAYER_ID);
    playerPosition = playerPromoted ? 'Semifinalista' : (D.playerExit || 'Fase de grupos');
    playerOutcome = playerPromoted
      ? 'Acesso à Série C conquistado!'
      : `Eliminado na ${playerPosition.toLowerCase()}.`;
  } else {
    const st = pd === 'A' ? stA : pd === 'B' ? stB : stC;
    const i = st.findIndex(r => r.club.id === PLAYER_ID);
    playerPosition = (i + 1) + 'º lugar';
    playerPromoted = pd !== 'A' && i < 4;
    playerRelegated = i >= 16;
    if (pd === 'A') {
      playerOutcome = i === 0 ? 'Campeão brasileiro!' : playerRelegated ? 'Rebaixado para a Série B.' : `${i + 1}º lugar na Série A.`;
    } else if (pd === 'B') {
      playerOutcome = playerPromoted ? 'Acesso à Série A!' : playerRelegated ? 'Rebaixado para a Série C.' : `${i + 1}º lugar na Série B.`;
    } else {
      playerOutcome = playerPromoted ? 'Acesso à Série B!' : playerRelegated ? 'Rebaixado para a Série D.' : `${i + 1}º lugar na Série C.`;
    }
  }

  return {
    season: S.season,
    championA: stA[0].club.name,
    championB: stB[0].club.name,
    championC: stC[0].club.name,
    championD: getClub(D.champion) ? getClub(D.champion).name : '—',
    playerDivision: pd,
    playerPosition,
    playerOutcome,
    playerPromoted,
    playerRelegated,
    promotedA: stB.slice(0, 4).map(r => r.club.name),
    relegatedA: stA.slice(-4).map(r => r.club.name),
    promotedB: stC.slice(0, 4).map(r => r.club.name),
    relegatedB: stB.slice(-4).map(r => r.club.name),
    promotedC: D.promoted.map(id => getClub(id).name),
    relegatedC: stC.slice(-4).map(r => r.club.name)
  };
}

function endSeason() {
  if (S.seasonEnded) return;
  fastForwardAll();
  S.pendingSeason = buildSeasonSummary();
  S.seasonEnded = true;
  S.match = null;
  S.history.push({
    season: S.pendingSeason.season,
    division: S.pendingSeason.playerDivision,
    outcome: S.pendingSeason.playerOutcome,
    championA: S.pendingSeason.championA
  });
  save();
  renderAll();
  if (S.screen !== 'match') openSeasonSummary();
}

function adjustStrength(c, delta) {
  c.strength = clamp(c.strength + delta, 55, 92);
}

function makeYouth(index) {
  const pos = pick(POS_ORDER);
  return {
    name: pick(FIRST_NAMES) + ' ' + pick(LAST_NAMES),
    pos, overall: 64 + rand(8), age: 18 + rand(3),
    number: 30 + index, goals: 0
  };
}

function startNextSeason() {
  if (!S.pendingSeason) return;
  const stA = standings(S.divisions.A.clubs, S.divisions.A.table).map(r => r.club);
  const stB = standings(S.divisions.B.clubs, S.divisions.B.table).map(r => r.club);
  const stC = standings(S.divisions.C.clubs, S.divisions.C.table).map(r => r.club);
  const D = S.divisions.D;
  const promotedD = D.promoted.map(getClub).filter(Boolean);

  const relegatedA = stA.slice(-4);
  const promotedB = stB.slice(0, 4);
  const relegatedB = stB.slice(-4);
  const promotedC = stC.slice(0, 4);
  const relegatedC = stC.slice(-4);

  const oldA = S.divisions.A.clubs;
  const oldB = S.divisions.B.clubs;
  const oldC = S.divisions.C.clubs;
  const oldD = D.groups.flatMap(g => g.clubs);

  const newA = oldA.filter(c => !relegatedA.some(x => x.id === c.id)).concat(promotedB);
  const newB = oldB.filter(c => !promotedB.some(x => x.id === c.id) && !relegatedB.some(x => x.id === c.id))
    .concat(relegatedA, promotedC);
  const newC = oldC.filter(c => !promotedC.some(x => x.id === c.id) && !relegatedC.some(x => x.id === c.id))
    .concat(relegatedB, promotedD);
  const newD = oldD.filter(c => !promotedD.some(x => x.id === c.id)).concat(relegatedC);

  promotedB.forEach(c => adjustStrength(c, 3));
  relegatedA.forEach(c => adjustStrength(c, -2));
  promotedC.forEach(c => adjustStrength(c, 3));
  relegatedB.forEach(c => adjustStrength(c, -2));
  promotedD.forEach(c => adjustStrength(c, 3));
  relegatedC.forEach(c => adjustStrength(c, -2));
  stA[0] && adjustStrength(stA[0], 2);
  stB[0] && adjustStrength(stB[0], 2);
  stC[0] && adjustStrength(stC[0], 2);

  if (newA.some(c => c.id === PLAYER_ID)) S.playerDivision = 'A';
  else if (newB.some(c => c.id === PLAYER_ID)) S.playerDivision = 'B';
  else if (newC.some(c => c.id === PLAYER_ID)) S.playerDivision = 'C';
  else S.playerDivision = 'D';

  S.squad.forEach((p, i) => {
    p.age++;
    p.goals = 0;
    if (p.age >= 36) {
      Object.assign(p, makeYouth(i));
    } else if (p.overall < 82 && Math.random() < 0.45) {
      p.overall++;
    }
  });

  S.season++;
  S.divisions = {
    A: buildLeagueDiv('A', newA),
    B: buildLeagueDiv('B', newB),
    C: buildLeagueDiv('C', newC),
    D: buildD(newD)
  };
  S.selectedDivision = S.playerDivision;
  S.selectedGroup = null;
  S.seasonEnded = false;
  S.pendingSeason = null;
  S.match = null;
  S.lastResults = [];
  S.screen = 'home';
  save();
  closeModal();
  renderAll();
  toast(`Temporada ${S.season} iniciada na ${DIV_SHORT[S.playerDivision]}`);
}

/* Motor da partida do jogador */
function tacticFactors(tactic, playerSide) {
  const atk = tactic === 'atacando' ? 1.28 : tactic === 'defendendo' ? 0.78 : 1;
  const def = tactic === 'atacando' ? 1.16 : tactic === 'defendendo' ? 0.74 : 1;
  return playerSide === 'home' ? { home: atk, away: def } : { home: def, away: atk };
}

function playerSquad() { return S.squad || []; }

function pickName(club) {
  if (club.id === PLAYER_ID) {
    const pool = playerSquad().filter(p => p.pos !== 'GOL');
    return pool.length ? pick(pool).name : 'Verde FC';
  }
  return pick(FIRST_NAMES) + ' ' + pick(LAST_NAMES);
}

function pickScorer(club) {
  if (club.id === PLAYER_ID) {
    const weights = { ATA: 6, PON: 4, MEI: 2.4, VOL: 1.1, LAT: 0.65, ZAG: 0.45, GOL: 0.04 };
    const pool = playerSquad();
    const total = pool.reduce((s, p) => s + (weights[p.pos] || 0.5), 0);
    let r = Math.random() * total;
    for (const p of pool) {
      r -= weights[p.pos] || 0.5;
      if (r <= 0) {
        p.goals = (p.goals || 0) + 1;
        return p.name;
      }
    }
    const p = pick(pool);
    p.goals = (p.goals || 0) + 1;
    return p.name;
  }
  return pick(FIRST_NAMES) + ' ' + pick(LAST_NAMES);
}

function matchEvent(text, type) {
  const m = S.match;
  if (!m) return;
  m.events.unshift({ min: m.minute, text, type: type || 'info' });
  if (m.events.length > 40) m.events.pop();
}

function scoreGoal(side) {
  const m = S.match;
  const idx = side === 'home' ? 0 : 1;
  const club = side === 'home' ? m.home : m.away;
  m.score[idx]++;
  m.stats.shots[idx]++;
  m.stats.onTarget[idx]++;
  const scorer = pickScorer(club);
  m.scorers.push({ club: club.name, name: scorer, min: m.minute });
  m.events.unshift({ min: m.minute, text: `⚽ GOL! ${scorer} marca para ${club.name}.`, type: 'goal' });
  m.ball = { x: side === 'home' ? 88 : 12, y: 42 + rand(16) };
  if (m.events.length > 40) m.events.pop();
}

function takeShot(side) {
  const m = S.match;
  const idx = side === 'home' ? 0 : 1;
  const club = side === 'home' ? m.home : m.away;
  m.stats.shots[idx]++;
  const name = pickName(club);
  if (Math.random() < 0.42) {
    m.stats.onTarget[idx]++;
    matchEvent(`${name} finaliza para o gol, mas a defesa afasta.`, 'shot');
  } else {
    matchEvent(`${name} arrisca de fora e a bola passa perto.`, 'shot');
  }
  m.ball = { x: side === 'home' ? 78 : 22, y: 25 + rand(50) };
}

function startMatch(fx) {
  if (!fx) fx = getPlayerFixture();
  if (!fx) { toast('Nenhuma partida disponível.'); return; }
  const home = getClub(fx.home);
  const away = getClub(fx.away);
  if (!home || !away) { toast('Partida inválida.'); return; }
  S.match = {
    stage: fx.stage, div: fx.div, roundIndex: fx.roundIndex,
    groupId: fx.groupId, koRound: fx.koRound, tieIndex: fx.tieIndex,
    home, away, score: [0, 0], minute: 0,
    events: [{ min: 0, text: `Bola rolando: ${home.name} x ${away.name}.`, type: 'info' }],
    stats: { poss: [50, 50], shots: [0, 0], onTarget: [0, 0], corners: [0, 0] },
    tactic: S.tactic, finished: false,
    knockout: fx.stage === 'ko', pens: null, winner: null,
    ball: { x: 50, y: 50 },
    playerSide: fx.home === PLAYER_ID ? 'home' : 'away',
    scorers: []
  };
  S.screen = 'match';
  save();
  renderAll();
}

function advanceLive(mins, silent) {
  const m = S.match;
  if (!m || m.finished) return;
  const chunks = Math.max(1, Math.ceil((mins || 5) / 5));
  for (let c = 0; c < chunks && !m.finished; c++) {
    m.minute = Math.min(90, m.minute + 5);
    const baseH = expectedGoals(m.home, m.away, 3);
    const baseA = expectedGoals(m.away, m.home, -3);
    const tf = tacticFactors(m.tactic, m.playerSide);
    const xgH = baseH * tf.home;
    const xgA = baseA * tf.away;

    let poss = 50 + (m.home.strength - m.away.strength) * 0.65;
    if (m.playerSide === 'home') {
      poss += m.tactic === 'defendendo' ? 3 : m.tactic === 'atacando' ? -3 : 0;
    } else {
      poss -= m.tactic === 'defendendo' ? 3 : m.tactic === 'atacando' ? -3 : 0;
    }
    poss = clamp(poss + rand(9) - 4, 32, 68);
    m.stats.poss = [Math.round(poss), 100 - Math.round(poss)];

    if (Math.random() < 0.26) takeShot('home');
    if (Math.random() < 0.26) takeShot('away');

    if (Math.random() < xgH * 5 / 90) scoreGoal('home');
    if (Math.random() < xgA * 5 / 90) scoreGoal('away');

    if (Math.random() < 0.055) {
      const side = Math.random() < 0.5 ? 'home' : 'away';
      const club = side === 'home' ? m.home : m.away;
      matchEvent(`Cartão amarelo para ${pickName(club)}.`, 'card');
    }
    if (Math.random() < 0.03) {
      const side = Math.random() < 0.5 ? 'home' : 'away';
      m.stats.corners[side === 'home' ? 0 : 1]++;
      m.ball = { x: side === 'home' ? 92 : 8, y: 30 + rand(40) };
      matchEvent(`Escanteio para o ${side === 'home' ? m.home.name : m.away.name}.`, 'corner');
    }
    if (m.minute >= 90) finishLiveMatch();
  }
  if (!silent) { renderMatch(); save(); }
}

function finishLiveMatch() {
  const m = S.match;
  if (!m || m.finished) return;
  m.finished = true;
  m.minute = 90;
  if (m.knockout && m.score[0] === m.score[1]) {
    m.pens = simulatePens(m.home, m.away);
    m.winner = m.pens[0] > m.pens[1] ? m.home.id : m.away.id;
    m.events.unshift({
      min: 90,
      text: `Disputa de pênaltis: ${m.pens[0]} x ${m.pens[1]}. ${getClub(m.winner).name} avança.`,
      type: 'goal'
    });
  } else {
    m.winner = m.score[0] > m.score[1] ? m.home.id : m.score[1] > m.score[0] ? m.away.id : null;
  }
  afterPlayerMatch(m);
  save();
  renderAll();
}

function simulatePlayerMatch() {
  const fx = getPlayerFixture();
  if (!fx) { toast('Nenhuma partida disponível.'); return; }
  const home = getClub(fx.home), away = getClub(fx.away);
  if (!home || !away) return;
  const r = simScore(home, away, fx.stage === 'ko');
  const playerHome = home.id === PLAYER_ID;
  const gf = playerHome ? r.hg : r.ag;
  const ga = playerHome ? r.ag : r.hg;
  const scorers = [];
  if (home.id === PLAYER_ID) {
    for (let i = 0; i < r.hg; i++) scorers.push({ club: home.name, name: pickScorer(home), min: 10 + rand(80) });
  }
  if (away.id === PLAYER_ID) {
    for (let i = 0; i < r.ag; i++) scorers.push({ club: away.name, name: pickScorer(away), min: 10 + rand(80) });
  }
  const m = {
    stage: fx.stage, div: fx.div, roundIndex: fx.roundIndex,
    groupId: fx.groupId, koRound: fx.koRound, tieIndex: fx.tieIndex,
    home, away, score: [r.hg, r.ag], minute: 90,
    events: [{ min: 90, text: 'Partida simulada pelo técnico.', type: 'info' }],
    stats: {
      poss: [50 + rand(11) - 5, 50 - rand(11) + 5],
      shots: [6 + rand(9), 6 + rand(9)],
      onTarget: [2 + rand(5), 2 + rand(5)],
      corners: [2 + rand(7), 2 + rand(7)]
    },
    tactic: S.tactic, finished: true,
    knockout: fx.stage === 'ko', pens: r.pens, winner: r.winner,
    ball: { x: 50, y: 50 },
    playerSide: playerHome ? 'home' : 'away',
    scorers, simulated: true
  };
  m.stats.poss = [m.stats.poss[0], 100 - m.stats.poss[0]];
  S.match = m;
  afterPlayerMatch(m);
  save();
  renderAll();
}

function afterPlayerMatch(m) {
  const playerHome = m.home.id === PLAYER_ID;
  const opp = playerHome ? m.away : m.home;
  const gf = playerHome ? m.score[0] : m.score[1];
  const ga = playerHome ? m.score[1] : m.score[0];
  let res = 'E';
  if (m.knockout && m.winner) res = m.winner === PLAYER_ID ? 'V' : 'D';
  else res = gf > ga ? 'V' : gf < ga ? 'D' : 'E';
  S.lastResults.unshift({
    season: S.season, comp: fixtureLabel(m), opponent: opp.name,
    gf, ga, home: playerHome, result: res, pens: m.pens
  });
  S.lastResults = S.lastResults.slice(0, 6);

  applyPlayerResult(m);
  advanceOtherDivisions();
  checkSeasonEnd();
  save();
}

function setTactic(t) {
  S.tactic = t;
  if (S.match && !S.match.finished) S.match.tactic = t;
  save();
  renderMatch();
  toast(t === 'atacando' ? 'Postura ofensiva' : t === 'defendendo' ? 'Postura defensiva' : 'Postura equilibrada');
}

function goMatch() {
  S.screen = 'match';
  renderAll();
  save();
}

/* Interface e navegação */
const $ = id => document.getElementById(id);

function esc(s) {
  return String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

function textColor(hex) {
  const h = (hex || '#2f9e5f').replace('#', '');
  const r = parseInt(h.slice(0, 2), 16), g = parseInt(h.slice(2, 4), 16), b = parseInt(h.slice(4, 6), 16);
  return (r * 299 + g * 587 + b * 114) / 1000 > 150 ? '#0b1b13' : '#ffffff';
}

function crest(club, size) {
  if (!club) return '<div class="crest sm" style="background:#24382c;color:#9fb2a4">?</div>';
  const cls = size === 'sm' ? ' sm' : size === 'xs' ? ' xs' : '';
  return `<div class="crest${cls}" style="background:${club.color};color:${textColor(club.color)}">${esc(club.short)}</div>`;
}

function formDots(row) {
  const f = (row && row.form ? row.form : []).slice(-5);
  if (!f.length) return '<span class="dot n">–</span>';
  return f.map(x => `<span class="dot ${x === 'V' ? 'w' : x === 'E' ? 'd' : 'l'}">${x}</span>`).join('');
}

function openModal(html) {
  $('modal').innerHTML = html;
  $('modalBack').classList.add('show');
}

function closeModal() {
  $('modalBack').classList.remove('show');
}

function toast(msg) {
  const el = $('toast');
  el.textContent = msg;
  el.classList.add('show');
  clearTimeout(toast._t);
  toast._t = setTimeout(() => el.classList.remove('show'), 2200);
}

const NAV_ITEMS = [
  { id: 'home', label: 'Central', icon: '◉' },
  { id: 'league', label: 'Competição', icon: '▦' },
  { id: 'squad', label: 'Elenco', icon: '♟' },
  { id: 'match', label: 'Partida', icon: '⚽' }
];

function showScreen(id) {
  if (!NAV_ITEMS.some(n => n.id === id)) return;
  S.screen = id;
  if (id === 'league') {
    if (!S.selectedDivision) S.selectedDivision = S.playerDivision;
    if (S.selectedDivision === 'D' && !S.selectedGroup) {
      const g = getPlayerGroup();
      S.selectedGroup = g ? g.id : 'A';
    }
  }
  renderAll();
  save();
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

function renderAll() {
  if (!S) return;
  renderSidebar();
  document.querySelectorAll('.screen').forEach(el => el.classList.remove('active'));
  const map = { home: 'screen-home', league: 'screen-league', squad: 'screen-squad', match: 'screen-match' };
  const el = $(map[S.screen] || 'screen-home');
  if (el) el.classList.add('active');
  const meta = {
    home: ['Central', `Temporada ${S.season} · ${DIV_SHORT[S.playerDivision]}`],
    league: ['Competição', DIV_NAME[S.selectedDivision || S.playerDivision]],
    squad: ['Elenco', `${S.squad.length} jogadores · Média ${Math.round(S.squad.reduce((a, p) => a + p.overall, 0) / S.squad.length)}`],
    match: ['Partida', fixtureLabel(getPlayerFixture())]
  }[S.screen] || ['Central', ''];
  $('pageTitle').textContent = meta[0];
  $('pageSub').textContent = meta[1];
  if (S.screen === 'home') renderHome();
  else if (S.screen === 'league') renderLeague();
  else if (S.screen === 'squad') renderSquad();
  else if (S.screen === 'match') renderMatch();
}

function renderSidebar() {
  $('seasonLabel').textContent = `Temporada ${S.season}`;
  $('divBadge').textContent = `Série ${S.playerDivision}`;
  $('nav').innerHTML = NAV_ITEMS.map(n =>
    `<button class="nav-btn ${S.screen === n.id ? 'active' : ''}" onclick="showScreen('${n.id}')">
      <span class="ic">${n.icon}</span><span>${n.label}</span>
    </button>`
  ).join('');
  const club = playerClub();
  const st = playerStatus();
  if (club) {
    $('clubCard').innerHTML = `
      <div class="club-row">${crest(club, 'sm')}
        <div><strong>${esc(club.name)}</strong><small>${DIV_SHORT[S.playerDivision]} · ${st.pos}º lugar</small></div>
      </div>
      <div class="club-meta"><span><b>${st.pts}</b> pts</span><span><b>${st.j}</b> jogos</span></div>`;
  }
}

function fixtureTeams(fx) {
  if (!fx) return { home: playerClub(), away: null };
  return { home: getClub(fx.home), away: getClub(fx.away) };
}

function renderHome() {
  const club = playerClub();
  const st = playerStatus();
  const fx = getPlayerFixture();
  const div = S.playerDivision;
  const homeClub = fx ? getClub(fx.home) : club;
  const awayClub = fx ? getClub(fx.away) : null;
  const divObj = div === 'D' ? null : S.divisions[div];
  const group = div === 'D' ? getPlayerGroup() : null;
  const progressTotal = div === 'D' ? (group ? group.schedule.length : 0) : (divObj ? divObj.schedule.length : 0);
  const progressDone = div === 'D' ? (group ? group.round : 0) : (divObj ? divObj.round : 0);
  const pct = progressTotal ? Math.round(progressDone / progressTotal * 100) : 0;
  const objective = div === 'A'
    ? 'Terminar no G4 e brigar pelo título brasileiro.'
    : div === 'D'
      ? 'Avançar de grupo e chegar às semifinais para conquistar o acesso à Série C.'
      : `Terminar no G4 e conquistar o acesso à Série ${div === 'B' ? 'A' : 'B'}.`;

  const rows = st.rows || [];
  let mini = rows.slice(0, 6);
  if (st.pos > 6) mini = mini.concat([rows[st.pos - 1]]);

  const nexts = upcomingPlayerFixtures(3);
  const recent = S.lastResults.slice(0, 3);

  const hero = fx ? `
    <div class="card hero">
      <div class="hero-top"><span>Próximo jogo · <b>${esc(fixtureLabel(fx))}</b></span><span>${fx.home === PLAYER_ID ? 'Em casa' : 'Fora de casa'}</span></div>
      <div class="teams">
        <div class="team">${crest(homeClub)}<b>${esc(homeClub.name)}</b><small>FOR ${homeClub.strength} · ${fx.home === PLAYER_ID ? 'Você' : 'Adversário'}</small></div>
        <div class="vs">VS</div>
        <div class="team">${crest(awayClub)}<b>${esc(awayClub.name)}</b><small>FOR ${awayClub.strength} · ${fx.away === PLAYER_ID ? 'Você' : 'Adversário'}</small></div>
      </div>
      <div class="hero-actions">
        <button class="btn btn-primary" onclick="goMatch()">Jogar partida</button>
        <button class="btn" onclick="simulatePlayerMatch()">Simular</button>
      </div>
    </div>` : `
    <div class="card hero">
      <div class="hero-top"><span>Temporada ${S.season}</span><span>${S.seasonEnded ? 'Encerrada' : 'Em andamento'}</span></div>
      <div class="teams">
        <div class="team">${crest(club)}<b>${esc(club.name)}</b><small>${DIV_SHORT[div]} · ${st.pos}º</small></div>
        <div class="vs">—</div>
        <div class="team">${crest(null)}<b>Sem jogo</b><small>${S.seasonEnded ? 'Veja o resumo' : 'Aguardando rodada'}</small></div>
      </div>
      <div class="hero-actions">
        <button class="btn btn-primary" onclick="${S.seasonEnded ? 'openSeasonSummary()' : "showScreen('league')"}">${S.seasonEnded ? 'Ver resumo da temporada' : 'Ver competição'}</button>
      </div>
    </div>`;

  $('screen-home').innerHTML = `
    <div class="grid home-grid">
      <div class="stack">
        ${hero}
        <div class="stat-strip">
          <div class="stat"><span>Posição</span><b>${st.pos}º</b><small>de ${st.total} clubes</small></div>
          <div class="stat"><span>Pontos</span><b>${st.pts}</b><small>${st.j} jogos disputados</small></div>
          <div class="stat"><span>Saldo de gols</span><b>${(rows[st.pos - 1] && rows[st.pos - 1].gd > 0 ? '+' : '') + (rows[st.pos - 1] ? rows[st.pos - 1].gd : 0)}</b><small>${rows[st.pos - 1] ? rows[st.pos - 1].gf + ' marcados · ' + rows[st.pos - 1].gs + ' sofridos' : ''}</small></div>
        </div>
        <div class="card">
          <div class="card-head"><h2>Últimos resultados</h2><button class="link" onclick="showScreen('league')">Ver competição</button></div>
          ${recent.length ? `<div class="fixtures">${recent.map(r => `
            <div class="fixture">
              <span class="fx-home"><span class="fx-team"><span class="team-name">${esc(r.home ? 'Verde FC' : r.opponent)}</span></span></span>
              <span class="fx-mid"><b>${r.home ? r.gf + ' × ' + r.ga : r.ga + ' × ' + r.gf}</b></span>
              <span class="fx-away"><span class="fx-team"><span class="team-name">${esc(r.home ? r.opponent : 'Verde FC')}</span></span></span>
            </div>`).join('')}</div>` : '<div class="empty"><span class="big">◌</span>Nenhuma partida disputada ainda.</div>'}
        </div>
      </div>
      <div class="stack">
        <div class="card obj-card">
          <h2>Objetivo da temporada</h2>
          <p>${objective}</p>
          <div class="progress"><i style="width:${pct}%"></i></div>
          <div class="progress-meta"><span>${div === 'D' && group ? 'Grupo ' + group.id : DIV_SHORT[div]}</span><span>${progressDone} de ${progressTotal} rodadas</span></div>
        </div>
        <div class="card">
          <div class="card-head"><h2>Classificação</h2><button class="link" onclick="showScreen('league')">Ver tudo</button></div>
          <div class="table-wrap mini-table">
            <table class="table">
              <thead><tr><th>#</th><th>Clube</th><th class="num">P</th><th class="num">J</th><th>Últimos</th></tr></thead>
              <tbody>${mini.map((r, i) => {
                const pos = rows.indexOf(r) + 1;
                return `<tr class="${r.club.id === PLAYER_ID ? 'me' : ''}">
                  <td class="num">${pos}</td>
                  <td><div class="club-cell">${crest(r.club, 'xs')}<b>${esc(r.club.short)}</b></div></td>
                  <td class="num"><b>${r.p}</b></td><td class="num">${r.j}</td>
                  <td><div class="form">${formDots(r)}</div></td>
                </tr>`;
              }).join('')}</tbody>
            </table>
          </div>
        </div>
        <div class="card">
          <div class="card-head"><h2>Calendário</h2><span class="mini">${div === 'D' ? 'Série D' : DIV_SHORT[div]}</span></div>
          ${nexts.length ? `<div class="fixtures">${nexts.map(f => {
            const h = getClub(f.home), a = getClub(f.away);
            const opp = f.home === PLAYER_ID ? a : h;
            return `<div class="fixture">
              <span class="fx-home"><span class="fx-team"><span class="team-name ${f.home === PLAYER_ID ? '' : 'dim'}">${esc(h.short)}</span></span></span>
              <span class="fx-mid"><b>${f.home === PLAYER_ID ? 'VS' : '@'}</b></span>
              <span class="fx-away"><span class="fx-team"><span class="team-name ${f.away === PLAYER_ID ? '' : 'dim'}">${esc(a.short)}</span></span></span>
            </div>`;
          }).join('')}</div>` : '<div class="empty">Sem jogos futuros.</div>'}
        </div>
      </div>
    </div>`;
}

function zoneClass(div, i, len) {
  if (div === 'A') {
    if (i < 4) return 'zone-blue';
    if (i < 8) return 'zone-gold';
    if (i >= len - 4) return 'zone-red';
    return '';
  }
  if (div === 'B' || div === 'C') {
    if (i < 4) return 'zone-green';
    if (i >= len - 4) return 'zone-red';
  }
  return '';
}

function tableHTML(rows, div, compact) {
  return `<table class="table">
    <thead><tr><th>#</th><th>Clube</th><th class="num">P</th><th class="num">J</th><th class="num">V</th><th class="num">E</th><th class="num">D</th><th class="num">GP</th><th class="num">GC</th><th class="num">SG</th><th>Últimos</th></tr></thead>
    <tbody>${rows.map((r, i) => `
      <tr class="${r.club.id === PLAYER_ID ? 'me' : ''} ${div ? zoneClass(div, i, rows.length) : ''}">
        <td class="num">${i + 1}</td>
        <td><div class="club-cell">${crest(r.club, 'xs')}<div><b>${esc(r.club.name)}</b><small>${esc(r.club.short)}</small></div></div></td>
        <td class="num"><b>${r.p}</b></td><td class="num">${r.j}</td><td class="num">${r.v}</td><td class="num">${r.e}</td><td class="num">${r.d}</td>
        <td class="num">${r.gf}</td><td class="num">${r.gs}</td><td class="num">${r.gd > 0 ? '+' : ''}${r.gd}</td>
        <td><div class="form">${formDots(r)}</div></td>
      </tr>`).join('')}</tbody>
  </table>`;
}

function fixturesHTML(fixtures, label) {
  if (!fixtures || !fixtures.length) return '<div class="empty">Nenhuma partida nesta rodada.</div>';
  return `<div class="fixtures">${fixtures.map(f => {
    const h = getClub(f.home), a = getClub(f.away);
    if (!h || !a) return '';
    const score = f.result ? `<b>${f.result.hg} × ${f.result.ag}</b>` : '<b>VS</b>';
    const isMe = f.home === PLAYER_ID || f.away === PLAYER_ID;
    return `<div class="fixture ${isMe ? 'me' : ''}">
      <span class="fx-home"><span class="fx-team"><span class="team-name">${esc(h.short)}</span>${crest(h, 'xs')}</span></span>
      <span class="fx-mid">${score}</span>
      <span class="fx-away"><span class="fx-team">${crest(a, 'xs')}<span class="team-name">${esc(a.short)}</span></span></span>
    </div>`;
  }).join('')}</div>`;
}

function bracketHTML(D) {
  if (!D.koRounds.length) return '';
  return `<div class="bracket">${D.koRounds.map(round => `
    <div class="ko-round"><h3>${round.name}</h3>
      ${round.ties.map(t => {
        const h = getClub(t.home), a = getClub(t.away);
        if (!h || !a) return '';
        const sc = t.score ? `${t.score[0]} × ${t.score[1]}${t.pens ? ` <small>(${t.pens[0]}-${t.pens[1]})</small>` : ''}` : '—';
        const me = t.home === PLAYER_ID || t.away === PLAYER_ID;
        return `<div class="ko-tie ${me ? 'me' : ''}">
          <div class="t">${crest(h, 'xs')}<span>${esc(h.short)}</span></div>
          <div class="sc"><b>${sc}</b></div>
          <div class="t away"><span>${esc(a.short)}</span>${crest(a, 'xs')}</div>
        </div>`;
      }).join('')}
    </div>`).join('')}</div>`;
}

function renderLeague() {
  const sel = S.selectedDivision || S.playerDivision;
  if (sel === 'D' && !S.selectedGroup) {
    const g = getPlayerGroup();
    S.selectedGroup = g ? g.id : 'A';
  }
  const tabs = DIV_ORDER.map(d => {
    const active = d === sel;
    return `<button class="tab ${active ? 'active' : ''}" onclick="selectDivision('${d}')">${DIV_SHORT[d]}${d === S.playerDivision ? ' •' : ''}</button>`;
  }).join('');

  let content = '';
  let fixtures = [];
  let fixturesLabel = '';
  if (sel === 'D') {
    const D = S.divisions.D;
    const groupId = S.selectedGroup || 'A';
    const group = D.groups.find(g => g.id === groupId) || D.groups[0];
    const rows = standings(group.clubs, group.table);
    const groupTabs = D.groups.map(g =>
      `<button class="tab ${g.id === groupId ? 'active' : ''}" onclick="selectGroup('${g.id}')">Grupo ${g.id}</button>`
    ).join('');
    fixtures = group.schedule[Math.min(group.round, group.schedule.length - 1)] || [];
    fixturesLabel = `Grupo ${group.id} · Rodada ${Math.min(group.round + 1, group.schedule.length)}`;
    content = `
      <div class="card">
        <div class="card-head"><h2>Grupo ${group.id}</h2><span class="mini">${group.round} de ${group.schedule.length} rodadas</span></div>
        <div class="tabs mt8">${groupTabs}</div>
        <div class="table-wrap mt12">${tableHTML(rows, null, false)}</div>
        <div class="legend"><span><i style="background:var(--green)"></i>Classificados ao mata-mata</span><span><i style="background:var(--lime)"></i>Seu clube</span></div>
      </div>
      ${D.koRounds.length ? `<div class="card"><div class="card-head"><h2>Mata-mata</h2><span class="mini">Jogo único · 4 semifinalistas sobem</span></div>${bracketHTML(D)}</div>` : ''}
      <div class="card"><div class="card-head"><h2>Rodada</h2><span class="mini">${fixturesLabel}</span></div>${fixturesHTML(fixtures)}</div>`;
  } else {
    const d = S.divisions[sel];
    const rows = standings(d.clubs, d.table);
    fixtures = d.schedule[Math.min(d.round, d.schedule.length - 1)] || [];
    fixturesLabel = `Rodada ${Math.min(d.round + 1, d.schedule.length)} de ${d.schedule.length}`;
    content = `
      <div class="card">
        <div class="card-head"><h2>${DIV_NAME[sel]}</h2><span class="mini">${d.round} de ${d.schedule.length} rodadas</span></div>
        <div class="table-wrap">${tableHTML(rows, sel, false)}</div>
        <div class="legend">
          ${sel === 'A' ? '<span><i style="background:var(--blue)"></i>Libertadores</span><span><i style="background:var(--gold)"></i>Sul-Americana</span>' : '<span><i style="background:var(--green)"></i>Acesso</span>'}
          <span><i style="background:var(--red)"></i>Rebaixamento</span>
          <span><i style="background:var(--lime)"></i>Seu clube</span>
        </div>
      </div>
      <div class="card"><div class="card-head"><h2>Rodada</h2><span class="mini">${fixturesLabel}</span></div>${fixturesHTML(fixtures)}</div>`;
  }

  const rules = {
    A: '20 clubes · 38 rodadas em turno e returno · 3 pontos por vitória · G4 Libertadores · Z4 rebaixamento.',
    B: '20 clubes · 38 rodadas em turno e returno · 3 pontos por vitória · 4 primeiros sobem à Série A · 4 últimos caem à Série C.',
    C: '20 clubes · 38 rodadas em turno e returno · 3 pontos por vitória · 4 primeiros sobem à Série B · 4 últimos caem à Série D.',
    D: '64 clubes · 8 grupos de 8 · 14 rodadas · os 2 melhores de cada grupo avançam · mata-mata em jogo único · os 4 semifinalistas sobem à Série C.'
  };

  $('screen-league').innerHTML = `
    <div class="tabs" style="margin-bottom:14px">${tabs}</div>
    ${sel !== S.playerDivision ? `<div class="notice" style="margin-bottom:14px">Você está disputando a ${DIV_SHORT[S.playerDivision]}. Esta é a visão da ${DIV_SHORT[sel]}.</div>` : ''}
    <div class="grid" style="grid-template-columns:minmax(0,1.5fr) minmax(280px,.7fr);align-items:start">
      <div class="stack">${content}</div>
      <div class="stack">
        <div class="card obj-card">
          <h2>Regulamento</h2>
          <p>${rules[sel]}</p>
          <div class="progress-meta mt12"><span>${DIV_NAME[sel]}</span><span>Temporada ${S.season}</span></div>
        </div>
        <div class="card">
          <div class="card-head"><h2>Resumo</h2></div>
          <div class="summary-grid">
            <div class="summary-item"><span>Clubes</span><b>${sel === 'D' ? 64 : 20}</b></div>
            <div class="summary-item"><span>Formato</span><b>${sel === 'D' ? 'Grupos + mata-mata' : 'Pontos corridos'}</b></div>
            <div class="summary-item"><span>Acesso</span><b>${sel === 'A' ? '—' : sel === 'D' ? '4 semifinalistas' : 'G4'}</b></div>
            <div class="summary-item"><span>Queda</span><b>${sel === 'D' ? '—' : 'Z4'}</b></div>
          </div>
        </div>
      </div>
    </div>`;
}

function selectDivision(d) {
  S.selectedDivision = d;
  if (d === 'D') {
    const g = getPlayerGroup();
    S.selectedGroup = g ? g.id : 'A';
  }
  renderLeague();
  save();
}

function selectGroup(id) {
  S.selectedGroup = id;
  renderLeague();
  save();
}

function renderSquad() {
  const avg = Math.round(S.squad.reduce((a, p) => a + p.overall, 0) / S.squad.length);
  const atk = Math.round(S.squad.filter(p => ['ATA', 'PON', 'MEI'].includes(p.pos)).reduce((a, p) => a + p.overall, 0) / S.squad.filter(p => ['ATA', 'PON', 'MEI'].includes(p.pos)).length);
  const mid = Math.round(S.squad.filter(p => ['VOL', 'MEI'].includes(p.pos)).reduce((a, p) => a + p.overall, 0) / S.squad.filter(p => ['VOL', 'MEI'].includes(p.pos)).length);
  const def = Math.round(S.squad.filter(p => ['GOL', 'ZAG', 'LAT'].includes(p.pos)).reduce((a, p) => a + p.overall, 0) / S.squad.filter(p => ['GOL', 'ZAG', 'LAT'].includes(p.pos)).length);
  const sorted = S.squad.slice().sort((a, b) => POS_ORDER.indexOf(a.pos) - POS_ORDER.indexOf(b.pos) || b.overall - a.overall);
  const topScorer = S.squad.slice().sort((a, b) => (b.goals || 0) - (a.goals || 0))[0];
  const tactics = [['atacando', 'Ofensiva'], ['equilibrado', 'Equilibrada'], ['defendendo', 'Defensiva']];

  $('screen-squad').innerHTML = `
    <div class="squad-summary">
      <div class="stat"><span>Média geral</span><b>${avg}</b><small>${S.squad.length} jogadores</small></div>
      <div class="stat"><span>Ataque</span><b>${atk}</b><small>Força ofensiva</small></div>
      <div class="stat"><span>Meio-campo</span><b>${mid}</b><small>Criação</small></div>
      <div class="stat"><span>Defesa</span><b>${def}</b><small>Solidez</small></div>
    </div>
    <div class="card" style="margin-bottom:16px">
      <div class="card-head"><h2>Postura padrão</h2><span class="mini">Usada ao iniciar cada partida</span></div>
      <div class="tactics">${tactics.map(([id, label]) => `<button class="tactic ${S.tactic === id ? 'active' : ''}" onclick="setDefaultTactic('${id}')">${label}</button>`).join('')}</div>
      <div class="flex between mt12"><span class="tiny muted">Artilheiro do elenco</span><span class="small"><b class="lime">${esc(topScorer.name)}</b> · ${topScorer.goals || 0} gols</span></div>
    </div>
    <div class="squad-grid">
      ${sorted.map(p => `<div class="player">
        <div class="player-top"><span class="pos ${p.pos}">${p.pos}</span><span class="rating">${p.overall}</span></div>
        <h3>${esc(p.name)}</h3>
        <div class="meta"><span>#${p.number} · ${p.age} anos</span><span>${p.goals || 0} gols</span></div>
        <div class="bar"><i style="width:${p.overall}%"></i></div>
      </div>`).join('')}
    </div>`;
}

function setDefaultTactic(t) {
  S.tactic = t;
  save();
  renderSquad();
  toast(t === 'atacando' ? 'Postura ofensiva definida' : t === 'defendendo' ? 'Postura defensiva definida' : 'Postura equilibrada definida');
}

function pitchHTML(m) {
  const home = [[7, 50], [22, 13], [22, 38], [22, 62], [22, 87], [40, 25], [40, 50], [40, 75], [58, 17], [58, 50], [58, 83]];
  const away = home.map(([x, y]) => [100 - x, y]);
  const dots = [];
  home.forEach(([x, y], i) => {
    dots.push(`<div class="pdot ${m.playerSide === 'home' ? 'us' : 'them'}" style="left:${x}%;top:${y}%">${i + 1}</div>`);
  });
  away.forEach(([x, y], i) => {
    dots.push(`<div class="pdot ${m.playerSide === 'away' ? 'us' : 'them'}" style="left:${x}%;top:${y}%">${i + 1}</div>`);
  });
  return `<div class="pitch">
    <div class="box left"></div><div class="box right"></div>
    <div class="box small left"></div><div class="box small right"></div>
    <div class="goal left"></div><div class="goal right"></div>
    ${dots.join('')}
    <div class="ball" style="left:${m.ball.x}%;top:${m.ball.y}%"></div>
  </div>`;
}

function statRow(label, h, a, unit) {
  const total = Math.max(1, h + a);
  return `<div class="stat-row">
    <b>${h}${unit || ''}</b>
    <div><div class="stat-bar"><i class="h" style="width:${h / total * 100}%"></i><i class="a" style="width:${a / total * 100}%"></i></div><div class="tiny muted" style="text-align:center;margin-top:3px">${label}</div></div>
    <b>${a}${unit || ''}</b>
  </div>`;
}

function tacticsHTML(current) {
  return `<div class="tactics">
    <button class="tactic ${current === 'atacando' ? 'active' : ''}" onclick="setTactic('atacando')">Ofensiva</button>
    <button class="tactic ${current === 'equilibrado' ? 'active' : ''}" onclick="setTactic('equilibrado')">Equilibrada</button>
    <button class="tactic ${current === 'defendendo' ? 'active' : ''}" onclick="setTactic('defendendo')">Defensiva</button>
  </div>`;
}

function matchPreHTML(fx) {
  if (!fx) {
    return `<div class="card"><div class="empty"><span class="big">⚽</span>Nenhuma partida disponível no momento.<br>${S.seasonEnded ? 'A temporada terminou.' : 'Aguardando a próxima rodada.'}</div>
      <div class="modal-actions"><button class="btn btn-primary" onclick="${S.seasonEnded ? 'openSeasonSummary()' : "showScreen('home')"}">${S.seasonEnded ? 'Ver resumo da temporada' : 'Voltar à Central'}</button></div></div>`;
  }
  const h = getClub(fx.home), a = getClub(fx.away);
  return `<div class="grid match-grid">
    <div class="card hero">
      <div class="hero-top"><span>${esc(fixtureLabel(fx))}</span><span>${fx.home === PLAYER_ID ? 'Em casa' : 'Fora de casa'}</span></div>
      <div class="teams">
        <div class="team">${crest(h)}<b>${esc(h.name)}</b><small>FOR ${h.strength} · ${fx.home === PLAYER_ID ? 'Você' : 'Adversário'}</small></div>
        <div class="vs">VS</div>
        <div class="team">${crest(a)}<b>${esc(a.name)}</b><small>FOR ${a.strength} · ${fx.away === PLAYER_ID ? 'Você' : 'Adversário'}</small></div>
      </div>
      <div class="hero-actions">
        <button class="btn btn-primary" onclick="startMatch()">Iniciar partida</button>
        <button class="btn" onclick="simulatePlayerMatch()">Simular partida</button>
      </div>
    </div>
    <div class="stack">
      <div class="card">
        <div class="card-head"><h2>Postura</h2><span class="mini">Afeta ataque e defesa</span></div>
        ${tacticsHTML(S.tactic)}
      </div>
      <div class="card">
        <div class="card-head"><h2>Forma recente</h2></div>
        <div class="flex between mt8"><span class="small">${esc(h.short)}</span><div class="form">${formDots(rowFor(h.id))}</div></div>
        <div class="flex between mt8"><span class="small">${esc(a.short)}</span><div class="form">${formDots(rowFor(a.id))}</div></div>
      </div>
      <div class="card">
        <div class="card-head"><h2>Informações</h2></div>
        <div class="scorers">
          <div><span>Competição</span><b>${esc(fixtureLabel(fx).split(' · ')[0])}</b></div>
          <div><span>Estádio</span><b>${esc(h.name)}</b></div>
          <div><span>Mando</span><b>${fx.home === PLAYER_ID ? 'Verde FC' : h.short}</b></div>
        </div>
      </div>
    </div>
  </div>`;
}

function matchLiveHTML(m) {
  const playerHome = m.playerSide === 'home';
  const gf = playerHome ? m.score[0] : m.score[1];
  const ga = playerHome ? m.score[1] : m.score[0];
  return `<div class="grid match-grid">
    <div class="stack">
      <div class="card scoreboard">
        <div class="sb-team">${crest(m.home, 'sm')}<div><b>${esc(m.home.name)}</b><small>${playerHome ? 'Você' : 'Adversário'}</small></div></div>
        <div class="sb-score"><div class="score">${m.score[0]} — ${m.score[1]}</div><div class="minute">${m.minute}' · ${esc(fixtureLabel(m))}</div></div>
        <div class="sb-team away"><div><b>${esc(m.away.name)}</b><small>${!playerHome ? 'Você' : 'Adversário'}</small></div>${crest(m.away, 'sm')}</div>
      </div>
      ${pitchHTML(m)}
    </div>
    <div class="match-side">
      <div class="card">
        <div class="card-head"><h2>Estatísticas</h2><span class="mini">${m.playerSide === 'home' ? 'Verde à esquerda' : 'Verde à direita'}</span></div>
        <div class="stats-list">
          ${statRow('Posse de bola', m.stats.poss[0], m.stats.poss[1], '%')}
          ${statRow('Finalizações', m.stats.shots[0], m.stats.shots[1])}
          ${statRow('No gol', m.stats.onTarget[0], m.stats.onTarget[1])}
          ${statRow('Escanteios', m.stats.corners[0], m.stats.corners[1])}
        </div>
        <div class="mt12">${tacticsHTML(m.tactic)}</div>
        <div class="controls">
          <button class="btn btn-primary" onclick="advanceLive(5)" ${m.minute >= 90 ? 'disabled' : ''}>Avançar 5 min</button>
          <button class="btn" onclick="advanceLive(90, true)" ${m.minute >= 90 ? 'disabled' : ''}>Simular restante</button>
        </div>
      </div>
      <div class="card">
        <div class="card-head"><h2>Narração</h2><span class="mini">${gf} × ${ga}</span></div>
        <div class="commentary">
          ${m.events.slice(0, 9).map(e => `<div class="event ${e.type === 'goal' ? 'goal' : ''}"><span class="min">${e.min}'</span><span>${esc(e.text)}</span></div>`).join('')}
        </div>
      </div>
    </div>
  </div>`;
}

function matchPostHTML(m) {
  const playerHome = m.playerSide === 'home';
  const gf = playerHome ? m.score[0] : m.score[1];
  const ga = playerHome ? m.score[1] : m.score[0];
  let res = gf > ga ? 'win' : gf < ga ? 'loss' : 'draw';
  let resLabel = res === 'win' ? 'Vitória' : res === 'loss' ? 'Derrota' : 'Empate';
  if (m.knockout && m.winner) {
    if (m.winner === PLAYER_ID) { res = 'win'; resLabel = 'Classificado'; }
    else { res = 'loss'; resLabel = 'Eliminado'; }
  }
  return `<div class="grid match-grid">
    <div class="card">
      <div class="scoreboard">
        <div class="sb-team">${crest(m.home, 'sm')}<div><b>${esc(m.home.name)}</b><small>${playerHome ? 'Você' : 'Adversário'}</small></div></div>
        <div class="sb-score"><div class="score">${m.score[0]} — ${m.score[1]}</div><div class="minute">Fim de jogo</div></div>
        <div class="sb-team away"><div><b>${esc(m.away.name)}</b><small>${!playerHome ? 'Você' : 'Adversário'}</small></div>${crest(m.away, 'sm')}</div>
      </div>
      <div class="result-big"><div class="score">${gf} × ${ga}</div><span class="tag ${res}">${resLabel}${m.pens ? ` · pênaltis ${m.pens[0]} × ${m.pens[1]}` : ''}</span></div>
      <div class="scorers">
        ${m.scorers.length ? m.scorers.map(s => `<div><span>${esc(s.name)} <small class="muted">${esc(s.club)}</small></span><b>${s.min}'</b></div>`).join('') : '<div><span>Sem gols na partida.</span><b>0 × 0</b></div>'}
      </div>
      <div class="controls">
        <button class="btn btn-primary" onclick="continueAfterMatch()">Continuar</button>
        ${S.seasonEnded ? '<button class="btn" onclick="openSeasonSummary()">Resumo da temporada</button>' : '<button class="btn" onclick="showScreen(\'home\')">Ir para a Central</button>'}
      </div>
    </div>
    <div class="match-side">
      <div class="card">
        <div class="card-head"><h2>Estatísticas</h2></div>
        <div class="stats-list">
          ${statRow('Posse de bola', m.stats.poss[0], m.stats.poss[1], '%')}
          ${statRow('Finalizações', m.stats.shots[0], m.stats.shots[1])}
          ${statRow('No gol', m.stats.onTarget[0], m.stats.onTarget[1])}
          ${statRow('Escanteios', m.stats.corners[0], m.stats.corners[1])}
        </div>
      </div>
      <div class="card">
        <div class="card-head"><h2>Narração</h2></div>
        <div class="commentary">
          ${m.events.slice(0, 8).map(e => `<div class="event ${e.type === 'goal' ? 'goal' : ''}"><span class="min">${e.min}'</span><span>${esc(e.text)}</span></div>`).join('')}
        </div>
      </div>
    </div>
  </div>`;
}

function renderMatch() {
  const m = S.match;
  if (m && m.finished) { $('screen-match').innerHTML = matchPostHTML(m); return; }
  if (m && !m.finished) { $('screen-match').innerHTML = matchLiveHTML(m); return; }
  $('screen-match').innerHTML = matchPreHTML(getPlayerFixture());
}

function continueAfterMatch() {
  const wasSeasonEnd = S.seasonEnded;
  S.match = null;
  S.screen = 'home';
  renderAll();
  save();
  if (wasSeasonEnd) openSeasonSummary();
}

function openSeasonSummary() {
  const p = S.pendingSeason;
  if (!p) { toast('Nenhuma temporada encerrada.'); return; }
  const good = p.playerPromoted || (p.playerDivision === 'A' && p.playerPosition === '1º lugar');
  openModal(`
    <h2>Temporada ${p.season} encerrada</h2>
    <p class="sub">Confira como terminou a temporada e quem subiu e desceu entre as quatro séries.</p>
    <div class="outcome ${good ? '' : 'bad'}">
      <span>Seu resultado</span>
      <b>${esc(p.playerOutcome)}</b>
      <div class="tiny muted mt8">${DIV_NAME[p.playerDivision]} · ${esc(p.playerPosition)}</div>
    </div>
    <div class="summary-grid">
      <div class="summary-item"><span>Campeão Série A</span><b>${esc(p.championA)}</b></div>
      <div class="summary-item"><span>Campeão Série B</span><b>${esc(p.championB)}</b></div>
      <div class="summary-item"><span>Campeão Série C</span><b>${esc(p.championC)}</b></div>
      <div class="summary-item"><span>Campeão Série D</span><b>${esc(p.championD)}</b></div>
    </div>
    <div class="summary-grid">
      <div class="summary-item"><span>Sobem para a Série A</span><b>${p.promotedA.map(esc).join(', ')}</b></div>
      <div class="summary-item"><span>Caem para a Série B</span><b>${p.relegatedA.map(esc).join(', ')}</b></div>
      <div class="summary-item"><span>Sobem para a Série B</span><b>${p.promotedB.map(esc).join(', ')}</b></div>
      <div class="summary-item"><span>Caem para a Série C</span><b>${p.relegatedB.map(esc).join(', ')}</b></div>
      <div class="summary-item"><span>Sobem para a Série C</span><b>${p.promotedC.map(esc).join(', ')}</b></div>
      <div class="summary-item"><span>Caem para a Série D</span><b>${p.relegatedC.map(esc).join(', ')}</b></div>
    </div>
    <div class="modal-actions">
      <button class="btn btn-primary" onclick="startNextSeason()">Iniciar temporada ${p.season + 1}</button>
      <button class="btn btn-ghost" onclick="closeModal()">Fechar</button>
    </div>`);
}

function newCareer() {
  openModal(`
    <h2>Nova carreira</h2>
    <p class="sub">Isso apaga o progresso salvo e começa uma nova jornada no Brasileirão Série D com o Verde FC.</p>
    <div class="modal-actions">
      <button class="btn btn-danger" onclick="resetCareer()">Começar do zero</button>
      <button class="btn btn-ghost" onclick="closeModal()">Cancelar</button>
    </div>`);
}

function resetCareer() {
  try { localStorage.removeItem(SAVE_KEY); } catch (e) { }
  S = createInitialState();
  closeModal();
  renderAll();
  save();
  toast('Nova carreira iniciada na Série D');
}

function init() {
  S = loadState() || createInitialState();
  if (S.playerDivision === 'D' && !S.selectedGroup) {
    const g = getPlayerGroup();
    S.selectedGroup = g ? g.id : 'A';
  }
  renderAll();
  if (S.seasonEnded) setTimeout(openSeasonSummary, 350);
}

init();

